package main

import (
	"fmt"
	"go/ast"
	"os"
	"path/filepath"
)

// ForceNew extraction for terraform-provider-google and
// terraform-provider-google-beta.
//
// Both providers are generated by Magic Modules from the same templates and
// share one source layout. The only difference is the top directory: "google"
// in the GA repository and "google-beta" in the beta one.
//
// A resource registers itself from an init() function in its service package:
//
//	registry.Schema{
//		Name:   "google_compute_instance",
//		Type:   registry.SchemaTypeResource,
//		Schema: ResourceComputeInstance(),
//	}.Register()
//
// That literal is the only place where the resource type string and its schema
// function meet, so it is what this extractor keys on. Two schema shapes follow
// from it:
//
//   - A plain resource: the named function returns &schema.Resource{Schema: ...},
//     the same SDKv2 shape the AWS extractor already walks.
//   - A merged resource: every IAM resource (and a few others, such as the
//     logging exclusions) is built by a shared constructor that takes the parent
//     resource's schema as a parameter and returns
//     &schema.Resource{Schema: tpgresource.MergeSchemas(BaseSchema, parentSpecificSchema)}.
//     The ForceNew arguments are split across the two halves: "role" and
//     "member" come from the base schema in tpgiamresource, "project" from the
//     parent schema in the service package. Both halves are walked.
//
// A registration whose schema cannot be resolved completely is counted as a gap
// and contributes nothing: a resource with half its ForceNew arguments looks
// fully covered, which is worse than one that is visibly missing.
func extractForceNewGoogle(sourceRoot string) (*forceNewIndex, error) {
	providerRoot, err := googleProviderRoot(sourceRoot)
	if err != nil {
		return nil, err
	}

	// The shared IAM constructors live in their own package and are called
	// from every service package, so this one is parsed once up front.
	iamPackage, err := parsePackage(filepath.Join(providerRoot, "tpgiamresource"))
	if err != nil {
		return nil, fmt.Errorf("parsing tpgiamresource: %w", err)
	}
	iamPackage.followSchemaHelpers = true

	serviceRoot := filepath.Join(providerRoot, "services")
	entries, err := os.ReadDir(serviceRoot)
	if err != nil {
		return nil, fmt.Errorf("reading %s: %w", serviceRoot, err)
	}

	index := newForceNewIndex()
	for _, entry := range entries {
		if !entry.IsDir() {
			continue
		}
		servicePackage, err := parsePackage(filepath.Join(serviceRoot, entry.Name()))
		if err != nil {
			fmt.Fprintf(os.Stderr, "forcenew-extractor: skipping %s: %v\n", entry.Name(), err)
			continue
		}
		servicePackage.followSchemaHelpers = true
		collectGoogleRegistrations(servicePackage, iamPackage, index)
	}
	return index, nil
}

// googleProviderRoot finds the directory holding services/ and tpgiamresource/:
// <src>/google for the GA provider, <src>/google-beta for the beta one.
func googleProviderRoot(sourceRoot string) (string, error) {
	for _, name := range []string{"google", "google-beta"} {
		candidate := filepath.Join(sourceRoot, name)
		if info, err := os.Stat(filepath.Join(candidate, "services")); err == nil && info.IsDir() {
			return candidate, nil
		}
	}
	return "", fmt.Errorf("%s has neither google/services nor google-beta/services", sourceRoot)
}

// googleSchemaPart is one schema map literal and the package its identifiers
// resolve in. A merged resource has two parts from two different packages.
type googleSchemaPart struct {
	schemaMap      *ast.CompositeLit
	servicePackage *packageIndex
}

// collectGoogleRegistrations finds every registry.Schema{...} literal of a
// managed resource in the package and walks the schema it registers.
func collectGoogleRegistrations(servicePackage, iamPackage *packageIndex, index *forceNewIndex) {
	for _, file := range servicePackage.files {
		ast.Inspect(file, func(node ast.Node) bool {
			literal, ok := node.(*ast.CompositeLit)
			if !ok {
				return true
			}
			if isSelectorType(literal.Type, "registry", "FrameworkResource") {
				collectGoogleFrameworkResource(literal, servicePackage, index)
				return false
			}
			if !isSelectorType(literal.Type, "registry", "Schema") {
				return true
			}
			resourceType, registrationKind, schemaExpression := readGoogleRegistration(literal)
			if resourceType == "" || schemaExpression == nil {
				return false
			}
			// Data sources are read paths with nothing to replace.
			if registrationKind != "SchemaTypeResource" && registrationKind != "SchemaTypeIAMResource" {
				return false
			}

			index.SDKResourcesSeen++
			parts, complete := resolveGoogleSchema(schemaExpression, servicePackage, iamPackage, 0)
			if !complete {
				return false
			}
			index.SDKResourcesResolved++
			for _, part := range parts {
				walkSDKSchemaMap(part.schemaMap, "", resourceType, part.servicePackage, nil, index)
			}
			return false
		})
	}
}

// collectGoogleFrameworkResource handles a Plugin Framework resource:
//
//	registry.FrameworkResource{Name: "google_storage_notification", Func: NewStorageNotificationResource}
//
// The constructor names the struct whose Schema method holds the schema, which
// is the shape the shared Framework walker already reads for AWS.
func collectGoogleFrameworkResource(literal *ast.CompositeLit, servicePackage *packageIndex, index *forceNewIndex) {
	var resourceType, constructorName string
	for _, element := range literal.Elts {
		entry, ok := element.(*ast.KeyValueExpr)
		if !ok {
			continue
		}
		key, ok := entry.Key.(*ast.Ident)
		if !ok {
			continue
		}
		switch key.Name {
		case "Name":
			resourceType, _ = basicString(entry.Value)
		case "Func":
			if identifier, ok := entry.Value.(*ast.Ident); ok {
				constructorName = identifier.Name
			}
		}
	}
	if resourceType == "" {
		return
	}

	index.FrameworkSeen++
	constructor, ok := servicePackage.funcs[constructorName]
	if !ok {
		return
	}
	typeName := frameworkReceiverType(constructor)
	method, ok := servicePackage.methods[typeName]["Schema"]
	if typeName == "" || !ok || method.Body == nil {
		return
	}
	schemaLiteral := frameworkSchemaLit(method)
	if schemaLiteral == nil {
		return
	}
	index.FrameworkResolved++
	walkFrameworkBlock(schemaLiteral, "", resourceType, servicePackage, nil, index)
}

// readGoogleRegistration reads the Name, Type and Schema fields of a
// registry.Schema{...} literal.
func readGoogleRegistration(literal *ast.CompositeLit) (resourceType, registrationKind string, schemaExpression ast.Expr) {
	for _, element := range literal.Elts {
		entry, ok := element.(*ast.KeyValueExpr)
		if !ok {
			continue
		}
		key, ok := entry.Key.(*ast.Ident)
		if !ok {
			continue
		}
		switch key.Name {
		case "Name":
			resourceType, _ = basicString(entry.Value)
		case "Type":
			if selector, ok := entry.Value.(*ast.SelectorExpr); ok {
				registrationKind = selector.Sel.Name
			}
		case "Schema":
			schemaExpression = entry.Value
		}
	}
	return resourceType, registrationKind, schemaExpression
}

// resolveGoogleSchema resolves the Schema field of a registration, which is
// always a call: ResourceComputeInstance(), ProjectIamMemberResource(), or
// tpgiamresource.ResourceIamBinding(IamProjectSchema, ...). It returns the
// schema map literals that make up the resource, and whether every one of them
// was found.
func resolveGoogleSchema(expression ast.Expr, callerPackage, iamPackage *packageIndex, depth int) ([]googleSchemaPart, bool) {
	// Wrappers are at most a couple of calls deep; this only guards against a
	// cycle.
	if depth > 4 {
		return nil, false
	}
	call, ok := expression.(*ast.CallExpr)
	if !ok {
		return nil, false
	}

	var function *ast.FuncDecl
	var functionPackage *packageIndex
	switch callee := call.Fun.(type) {
	case *ast.Ident:
		function, functionPackage = callerPackage.funcs[callee.Name], callerPackage
	case *ast.SelectorExpr:
		if packageName, ok := callee.X.(*ast.Ident); ok && packageName.Name == "tpgiamresource" {
			function, functionPackage = iamPackage.funcs[callee.Sel.Name], iamPackage
		}
	}
	if function == nil || function.Body == nil {
		return nil, false
	}

	schemaField := resourceSchemaField(function)
	if schemaField == nil {
		// No schema.Resource literal here: a wrapper such as
		// ProjectIamMemberResource() that returns another constructor call.
		returned := returnedCall(function)
		if returned == nil {
			return nil, false
		}
		return resolveGoogleSchema(returned, functionPackage, iamPackage, depth+1)
	}

	merged, ok := schemaField.(*ast.CallExpr)
	if !ok || !isSelectorType(merged.Fun, "tpgresource", "MergeSchemas") {
		// A plain resource. The shared SDKv2 resolver handles inline maps,
		// package-level vars and schema functions.
		schemaMap := resolveSDKSchemaMap(function, functionPackage)
		if schemaMap == nil {
			return nil, false
		}
		return []googleSchemaPart{{schemaMap, functionPackage}}, true
	}

	// tpgresource.MergeSchemas(BaseSchema, parentSpecificSchema): an argument
	// that names one of the function's parameters is resolved from what the
	// caller passed, anything else from the function's own package.
	parameterIndex := functionParameterIndex(function)
	var parts []googleSchemaPart
	for _, argument := range merged.Args {
		if identifier, ok := argument.(*ast.Ident); ok {
			if position, isParameter := parameterIndex[identifier.Name]; isParameter {
				if position >= len(call.Args) {
					return nil, false
				}
				schemaMap := resolveSchemaMapExpr(call.Args[position], callerPackage)
				if schemaMap == nil {
					return nil, false
				}
				parts = append(parts, googleSchemaPart{schemaMap, callerPackage})
				continue
			}
		}
		schemaMap := resolveSchemaMapExpr(argument, functionPackage)
		if schemaMap == nil {
			return nil, false
		}
		parts = append(parts, googleSchemaPart{schemaMap, functionPackage})
	}
	return parts, len(parts) > 0
}

// resourceSchemaField returns the value of the Schema field of the first
// schema.Resource literal in a function, or nil when there is none.
func resourceSchemaField(function *ast.FuncDecl) ast.Expr {
	var value ast.Expr
	ast.Inspect(function.Body, func(node ast.Node) bool {
		if value != nil {
			return false
		}
		literal, ok := node.(*ast.CompositeLit)
		if !ok || !isSchemaSelector(literal.Type, "Resource") {
			return true
		}
		for _, element := range literal.Elts {
			entry, ok := element.(*ast.KeyValueExpr)
			if !ok {
				continue
			}
			if key, ok := entry.Key.(*ast.Ident); ok && (key.Name == "Schema" || key.Name == "SchemaFunc") {
				value = entry.Value
				return false
			}
		}
		// The first schema.Resource literal is the resource itself; nested
		// ones belong to its blocks and must not be mistaken for it.
		return false
	})
	return value
}

// returnedCall returns the call expression a function returns, for wrappers
// like `func ProjectIamMemberResource() *schema.Resource { return tpgiamresource.ResourceIamMember(...) }`.
func returnedCall(function *ast.FuncDecl) *ast.CallExpr {
	var call *ast.CallExpr
	ast.Inspect(function.Body, func(node ast.Node) bool {
		if call != nil {
			return false
		}
		if _, isClosure := node.(*ast.FuncLit); isClosure {
			return false
		}
		returnStatement, ok := node.(*ast.ReturnStmt)
		if !ok || len(returnStatement.Results) != 1 {
			return true
		}
		call, _ = returnStatement.Results[0].(*ast.CallExpr)
		return false
	})
	return call
}

// functionParameterIndex maps each parameter name to its position.
func functionParameterIndex(function *ast.FuncDecl) map[string]int {
	positions := map[string]int{}
	if function.Type.Params == nil {
		return positions
	}
	position := 0
	for _, field := range function.Type.Params.List {
		if len(field.Names) == 0 {
			position++
			continue
		}
		for _, name := range field.Names {
			positions[name.Name] = position
			position++
		}
	}
	return positions
}
